/* tex_sprite.c - the texture-pipeline sample.
 *
 * Uploads two textures to VRAM through psx_tim_upload, one 8-bit paletted and
 * one 16-bit direct color, then draws each as a sprite every frame. Both come
 * from the same four-quadrant test pattern (red, green, blue, white), so the
 * framebuffer check can probe known colors at known screen positions and prove
 * the whole path: TIM parse, VRAM upload, palette, texture page, and the
 * textured-rectangle primitive.
 *
 * The TIM blobs are generated by timconv and linked in as C arrays. It exits 0
 * after its loop, which the emulator reports in test mode.
 */

#include "psx.h"

extern const unsigned char psx_tex8[];
extern const unsigned      psx_tex8_len;
extern const unsigned char psx_tex16[];
extern const unsigned      psx_tex16_len;

#define FRAMES 120

int
main(void)
{
    psx_texinfo t8, t16;

    psx_gpu_init();
    psx_irq_init();
    psx_set_bg(0, 20, 0);                       /* dark green field */

    if (psx_tim_upload(psx_tex8, &t8) != 0)
        return 2;
    if (psx_tim_upload(psx_tex16, &t16) != 0)
        return 3;

    for (int f = 0; f < FRAMES; f++) {
        psx_draw_sprite(&t8, 48, 40);           /* 8-bit sprite, left */
        psx_draw_sprite(&t16, 208, 40);         /* 16-bit sprite, right */
        psx_vsync();
        psx_display_swap();
    }

    return 0;
}
